"use client";

import { useEffect, useRef, type CSSProperties, type ReactNode } from "react";
import { ExtensionPopup } from "./ExtensionPopup";
import { PlayerControls } from "./PlayerControls";
import { HeroDemoProvider, useHeroDemo } from "./state";
import { TranscriptCard } from "./TranscriptCard";
import { VideoFrame } from "./VideoFrame";

/** The stage backdrop: a dim room with warm stage light, like the paused frame of a talk. */
function Backdrop({ className = "" }: { className?: string }) {
  return <div className={`hero-backdrop hero-focus pointer-events-none absolute inset-0 ${className}`} aria-hidden="true" />;
}

/**
 * The right side of the hero: real pieces of Heard, composed like a collage.
 *
 * On wide screens the pieces sit on a fixed canvas that scales to fit the stage, so a composition
 * holds at every size. Narrower screens stack the same pieces. They arrive one at a time: the
 * player, its controls, the transcript, then the extension popup.
 */
export function HeroDemo() {
  return (
    <HeroDemoProvider>
      <DemoLayout />
    </HeroDemoProvider>
  );
}

/** A piece's place on the canvas: position, width, optional height, and tilt in degrees. */
interface Spot {
  x: number;
  y: number;
  w?: number;
  h?: number;
  r: number;
}
interface Layout {
  w: number;
  h: number;
  video: Spot;
  controls: Spot;
  transcript: Spot;
  popup: Spot;
}

/*
 * The composition: a tight diagonal from top left to bottom right, each piece tilted a little and
 * tucked against the one before: the video, the transcript just under its controls, then the
 * extension popup over the transcript's bottom corner. Sizes: the video is 16:9 at its
 * width, the controls pill is about 300×52, the popup about 256×150.
 */
const LAYOUT: Layout = {
  w: 560,
  h: 660,
  video: { x: 0, y: 0, w: 440, r: -3 },
  controls: { x: 40, y: 220, r: -2 },
  transcript: { x: 150, y: 262, w: 260, h: 250, r: 1.5 },
  popup: { x: 300, y: 500, w: 256, r: 4 },
};

const MAX_SCALE = 1.4;

/** Scales the wide-screen canvas to fit its box (a CSS variable, so it costs no re-render). */
function useCanvasScale(w: number, h: number) {
  const boxRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const box = boxRef.current;
    if (!box) return;
    const wide = window.matchMedia("(min-width: 1280px)");
    const update = () => {
      if (!wide.matches) {
        box.style.removeProperty("--demo-scale");
        return;
      }
      const rect = box.getBoundingClientRect();
      const s = Math.min(rect.width / w, rect.height / h, MAX_SCALE);
      box.style.setProperty("--demo-scale", String(Math.max(0.5, s)));
    };
    update();
    const ro = new ResizeObserver(update);
    ro.observe(box);
    wide.addEventListener("change", update);
    return () => {
      ro.disconnect();
      wide.removeEventListener("change", update);
    };
  }, [w, h]);
  return boxRef;
}

function spotStyle(s: Spot): CSSProperties {
  return {
    "--x": `${s.x}px`,
    "--y": `${s.y}px`,
    "--w": s.w ? `${s.w}px` : "auto",
    "--h": s.h ? `${s.h}px` : "auto",
    "--r": `${s.r}deg`,
  } as CSSProperties;
}

/** One piece on the canvas. Below xl it just flows in the stacked column (`className`). */
function Piece({ spot, delay, className = "", children, hidden }: { spot: Spot; delay: number; className?: string; children: ReactNode; hidden?: boolean }) {
  return (
    <div
      hidden={hidden}
      className={`hero-pop relative xl:absolute xl:top-[var(--y)] xl:left-[var(--x)] xl:mt-0 xl:ml-0 xl:h-[var(--h)] xl:w-[var(--w)] xl:max-w-none ${className}`}
      style={{ ...spotStyle(spot), animationDelay: `${delay}ms` }}
    >
      <div className="h-full xl:rotate-[var(--r)]">{children}</div>
    </div>
  );
}

function DemoLayout() {
  const { showTranscript, captionsOn, playing } = useHeroDemo();
  const listening = captionsOn && playing;
  const layout = LAYOUT;
  const boxRef = useCanvasScale(layout.w, layout.h);

  return (
    <>
      <Backdrop className="hidden rounded-[32px] xl:block" />
      <div
        className="relative mt-14 overflow-hidden rounded-[28px] px-5 pt-9 pb-8 sm:px-10 sm:pt-12 sm:pb-12 xl:absolute xl:inset-y-0 xl:right-0 xl:left-[52%] xl:mt-0 xl:overflow-visible xl:rounded-none xl:p-0 2xl:left-[48%]"
        data-hero-demo
        role="group"
        aria-label="Try Heard: a demo player with live captions, the Chrome extension popup and the transcript"
      >
        <Backdrop className="xl:hidden" />

        {/* The box the canvas scales into: clear of the extension button above, with room all round. */}
        <div ref={boxRef} className="relative xl:absolute xl:inset-x-[5%] xl:top-24 xl:bottom-12">
          <div
            className="relative mx-auto flex max-w-[36rem] flex-col xl:absolute xl:top-1/2 xl:left-1/2 xl:block xl:h-[var(--ch)] xl:w-[var(--cw)] xl:max-w-none xl:-translate-x-1/2 xl:-translate-y-1/2 xl:[scale:var(--demo-scale,1)]"
            style={{ "--cw": `${layout.w}px`, "--ch": `${layout.h}px` } as CSSProperties}
          >
            <Piece spot={layout.video} delay={350}>
              <div className="relative">
                <VideoFrame />
                <span
                  className="absolute -top-4 -left-3 grid h-11 w-11 place-items-center rounded-full bg-ink-950 shadow-[0_8px_24px_-8px_rgba(0,0,0,0.9)] ring-1 ring-white/10"
                  title={listening ? "Listening" : "Not listening"}
                >
                  <span className="flex h-4 items-center gap-[3px]">
                    {[0, 1, 2, 3].map((i) => (
                      <span
                        key={i}
                        className={`w-[3px] rounded-full transition-colors ${listening ? "hero-bar bg-accent" : "h-1 bg-ink-600"}`}
                        style={{ animationDelay: `${i * 140}ms` }}
                      />
                    ))}
                  </span>
                </span>
              </div>
            </Piece>

            <Piece spot={layout.controls} delay={950} className="z-20 mt-4 flex justify-center">
              <PlayerControls />
            </Piece>

            <Piece spot={layout.transcript} delay={1550} hidden={!showTranscript} className="z-10 mt-6 w-full max-w-[19rem]">
              <TranscriptCard />
            </Piece>

            <Piece spot={layout.popup} delay={2150} className="z-30 -mt-4 ml-auto w-[15.5rem]">
              <div className="-rotate-2 xl:rotate-0">
                <ExtensionPopup />
              </div>
            </Piece>
          </div>
        </div>

      </div>
    </>
  );
}

/** Small icons shared by the hero demo pieces. */

import { forwardRef, type ButtonHTMLAttributes, type ReactNode } from "react";

export function CaptionsGlyph() {
  return (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      <rect x="3" y="6" width="18" height="12" rx="2.5" />
      <path d="M10 10.5a2 2 0 1 0 0 3M16 10.5a2 2 0 1 0 0 3" />
    </svg>
  );
}

/** Round icon button for the demo's player controls. `active` shows the pressed style. */
export const ToolIcon = forwardRef<
  HTMLButtonElement,
  { children: ReactNode; active?: boolean; label: string } & Omit<ButtonHTMLAttributes<HTMLButtonElement>, "children" | "aria-label">
>(function ToolIcon({ children, active = false, label, className = "", title, ...rest }, ref) {
  return (
    <button
      ref={ref}
      type="button"
      aria-label={label}
      title={title ?? label}
      className={`inline-flex h-10 w-10 shrink-0 items-center justify-center rounded-full transition-colors hover:bg-ink-800 hover:text-ink-100 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent ${
        active ? "bg-ink-800 text-ink-100" : "text-ink-400"
      } ${className}`}
      {...rest}
    >
      <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
        {children}
      </svg>
    </button>
  );
});

{
  "version": "0.0.1",
  "configurations": [
    {
      "name": "heard-web",
      "runtimeExecutable": "/bin/sh",
      "runtimeArgs": ["-c", "PATH=\"$HOME/.nvm/versions/node/v22.23.1/bin:$PATH\" npm run dev:web"],
      "port": 3100
    }
  ]
}

import type { ParsedVideo, ParseProblem, VideoProvider } from "./types";
import { isParseProblem } from "./types";
import { youtubeProvider } from "./youtube";

export * from "./types";

/** Every supported provider. Add Twitch / Vimeo / direct-media providers here. */
export const PROVIDERS: VideoProvider[] = [youtubeProvider];

export function getProvider(id: string): VideoProvider | undefined {
  return PROVIDERS.find((p) => p.id === id);
}

export type ResolveResult =
  | { ok: true; provider: VideoProvider; video: ParsedVideo }
  | { ok: false; message: string };

/** Accepts what people paste: full URLs, URLs without a scheme, or surrounding whitespace. */
export function toUrl(input: string): URL | null {
  const raw = input.trim();
  if (!raw) return null;
  try {
    return new URL(/^[a-z][a-z0-9+.-]*:\/\//i.test(raw) ? raw : `https://${raw}`);
  } catch {
    return null;
  }
}

export function resolveVideo(input: string): ResolveResult {
  const url = toUrl(input);
  if (!url) return { ok: false, message: "Paste a full video link, like https://www.youtube.com/watch?v=…" };
  for (const provider of PROVIDERS) {
    const parsed: ParsedVideo | ParseProblem | null = provider.parse(url);
    if (!parsed) continue;
    if (isParseProblem(parsed)) return { ok: false, message: parsed.message };
    return { ok: true, provider, video: parsed };
  }
  return {
    ok: false,
    message: "Heard doesn't recognize that link yet. YouTube videos, Shorts and livestreams are supported.",
  };
}

export function watchHref(input: string): string {
  return `/watch?url=${encodeURIComponent(input.trim())}`;
}

"use client";

import { useEffect, useRef, useState, type KeyboardEvent, type PointerEvent } from "react";
import { DURATION, SCRIPT, formatTime, useHeroDemo } from "./state";

/** How fast the simulated recognizer reveals words. */
const WORDS_PER_SEC = 3;
/** How long the play/pause glyph lingers after resuming. */
const FLASH_MS = 650;

function prefersReducedMotion(): boolean {
  return typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

/** The player: the video with Heard's live caption overlay. */
export function VideoFrame() {
  const { time, playing, captionsOn, showCaptions, current, togglePlaying, seek } = useHeroDemo();

  // Live caption: the current line, revealed a few words at a time.
  const line = current !== null && captionsOn && showCaptions ? SCRIPT[current] : undefined;
  const allWords = line ? line.text.split(" ") : [];
  const revealed = line ? Math.min(allWords.length, Math.floor(Math.max(0, time - line.t) * WORDS_PER_SEC) + 1) : 0;
  const words = allWords.slice(0, revealed);

  // Briefly show the pause glyph after resuming; the play glyph stays while paused.
  const [flash, setFlash] = useState(false);
  const flashTimer = useRef<number | undefined>(undefined);
  useEffect(() => () => window.clearTimeout(flashTimer.current), []);
  const onToggle = () => {
    window.clearTimeout(flashTimer.current);
    if (!playing && !prefersReducedMotion()) {
      setFlash(true);
      flashTimer.current = window.setTimeout(() => setFlash(false), FLASH_MS);
    } else {
      setFlash(false);
    }
    togglePlaying();
  };
  const glyphVisible = !playing || flash;

  // Scrubbing.
  const barRef = useRef<HTMLDivElement>(null);
  const [hoverX, setHoverX] = useState<number | null>(null);
  const fractionAt = (clientX: number): number => {
    const rect = barRef.current?.getBoundingClientRect();
    if (!rect || rect.width === 0) return 0;
    return Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
  };
  const onBarDown = (e: PointerEvent<HTMLDivElement>) => {
    if (e.button !== 0) return;
    e.currentTarget.setPointerCapture(e.pointerId);
    seek(fractionAt(e.clientX) * DURATION);
  };
  const onBarMove = (e: PointerEvent<HTMLDivElement>) => {
    const f = fractionAt(e.clientX);
    setHoverX(f);
    if (e.currentTarget.hasPointerCapture(e.pointerId)) seek(f * DURATION);
  };
  const onBarKey = (e: KeyboardEvent<HTMLDivElement>) => {
    const step = e.shiftKey ? 10 : 5;
    let next: number | null = null;
    if (e.key === "ArrowRight" || e.key === "ArrowUp") next = time + step;
    else if (e.key === "ArrowLeft" || e.key === "ArrowDown") next = time - step;
    else if (e.key === "Home") next = 0;
    else if (e.key === "End") next = DURATION;
    if (next === null) return;
    e.preventDefault();
    seek(next);
  };

  const progress = Math.max(0, Math.min(1, time / DURATION));

  return (
    <div className="relative aspect-video overflow-hidden rounded-2xl bg-[#0b0b10] shadow-[0_30px_60px_-24px_rgba(0,0,0,0.95)] ring-1 ring-white/10">
      <svg viewBox="0 0 160 90" preserveAspectRatio="xMidYMax slice" className="absolute inset-0 h-full w-full" aria-hidden="true">
        <defs>
          <linearGradient id="hero-spot" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="#f5b83d" stopOpacity="0.22" />
            <stop offset="1" stopColor="#f5b83d" stopOpacity="0" />
          </linearGradient>
          <radialGradient id="hero-floor" cx="0.5" cy="0.5" r="0.5">
            <stop offset="0" stopColor="#f5b83d" stopOpacity="0.16" />
            <stop offset="1" stopColor="#f5b83d" stopOpacity="0" />
          </radialGradient>
        </defs>
        <rect width="160" height="90" fill="#101016" />
        <path d="M72 0h16l30 90H42z" fill="url(#hero-spot)" />
        <ellipse cx="80" cy="89" rx="50" ry="8" fill="url(#hero-floor)" />
        <g className={`transition-opacity duration-500 motion-reduce:transition-none ${playing ? "opacity-100" : "opacity-60"}`}>
          <circle cx="80" cy="44" r="7.5" fill="#2c2b36" />
          <path d="M63 90c0-20 7.5-34 17-34s17 14 17 34z" fill="#2c2b36" />
        </g>
      </svg>

      {/* The whole picture is the play/pause control, under the overlays. */}
      <button
        type="button"
        onClick={onToggle}
        aria-label={playing ? "Pause video" : "Play video"}
        className="absolute inset-0 flex cursor-pointer items-center justify-center rounded-2xl focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent focus-visible:ring-inset"
      >
        <span
          aria-hidden="true"
          className={`flex h-12 w-12 items-center justify-center rounded-full bg-black/55 text-white/90 backdrop-blur-sm transition-opacity duration-300 motion-reduce:transition-none sm:h-14 sm:w-14 ${glyphVisible ? "opacity-100" : "opacity-0"}`}
        >
          {playing ? (
            <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor">
              <rect x="6" y="5" width="4" height="14" rx="1" />
              <rect x="14" y="5" width="4" height="14" rx="1" />
            </svg>
          ) : (
            <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor" className="translate-x-[1px]">
              <path d="M8 5.5v13a1 1 0 0 0 1.5.86l10.5-6.5a1 1 0 0 0 0-1.72L9.5 4.64A1 1 0 0 0 8 5.5z" />
            </svg>
          )}
        </span>
      </button>

      {captionsOn ? (
        <span className="pointer-events-none absolute top-3 right-3 inline-flex xl:right-auto xl:left-12 items-center gap-1.5 rounded-full bg-black/60 px-2.5 py-1 text-[11px] font-semibold text-live backdrop-blur">
          <span className="h-1.5 w-1.5 animate-pulse-dot rounded-full bg-live" />
          Live captions
        </span>
      ) : (
        <span className="pointer-events-none absolute top-3 right-3 inline-flex xl:right-auto xl:left-12 items-center rounded-full bg-black/60 px-2.5 py-1 text-[11px] font-semibold text-ink-400 backdrop-blur">
          Captions off
        </span>
      )}

      {/* At most two caption lines; older lines roll off the top as words arrive. */}
      <div
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-3 bottom-5 flex max-h-[3.5em] xl:inset-x-8 xl:bottom-11 flex-col justify-end overflow-hidden text-[12.5px] leading-[1.75] sm:bottom-6 sm:text-sm"
      >
        {line && (
          <p className="text-center font-medium text-white">
            {/* Each word carries its own caption background, so the bar grows as words arrive. */}
            {words.map((w, i) => (
              <span
                key={`${current}-${i}`}
                className={`bg-black/85 py-[3px] motion-safe:animate-[word-in_220ms_ease-out_both] ${i === 0 ? "rounded-l pl-2" : ""} ${i === words.length - 1 ? "rounded-r pr-2" : ""}`}
              >
                {w}
                {i < words.length - 1 ? " " : ""}
              </span>
            ))}
          </p>
        )}
      </div>

      {/* Seek bar: a 12px hit area over the 3px track. */}
      <div
        ref={barRef}
        role="slider"
        tabIndex={0}
        aria-label="Seek"
        aria-valuemin={0}
        aria-valuemax={DURATION}
        aria-valuenow={Math.floor(time)}
        aria-valuetext={`${formatTime(time)} of ${formatTime(DURATION)}`}
        onPointerDown={onBarDown}
        onPointerMove={onBarMove}
        onPointerLeave={() => setHoverX(null)}
        onKeyDown={onBarKey}
        className="group absolute inset-x-0 bottom-0 h-3 cursor-pointer touch-none focus-visible:outline-none"
      >
        <div className="absolute inset-x-0 bottom-0 h-[3px] bg-white/10 transition-[height] duration-150 group-hover:h-[5px] group-focus-visible:h-[5px] motion-reduce:transition-none">
          <div className="h-full bg-accent" style={{ width: `${progress * 100}%` }} />
        </div>
        <div className="pointer-events-none absolute inset-x-0 bottom-0 hidden h-[5px] ring-2 ring-accent ring-inset group-focus-visible:block" />
        {hoverX !== null && (
          <span
            className="pointer-events-none absolute bottom-3 -translate-x-1/2 rounded bg-black/80 px-1.5 py-0.5 text-[10px] font-medium text-white tabular-nums"
            style={{ left: `clamp(16px, ${hoverX * 100}%, calc(100% - 16px))` }}
          >
            {formatTime(hoverX * DURATION)}
          </span>
        )}
      </div>
    </div>
  );
}

