/**
 * Caption translation with Chrome's built-in, on-device Translator API
 * (developer.chrome.com/docs/ai/translator-api). Deepgram transcribes in the spoken language;
 * this turns that text into the viewer's language without any server or key: the model runs
 * in the browser and text never leaves it.
 *
 * Each language pair is a one-time download that Chrome only starts from a click, so the
 * settings UI calls `prepareTranslator` from its change handler, and the running session
 * reports a `download` issue when it meets a pair that isn't on the device yet.
 */
import { AUTO_LANGUAGE } from "./settings";
import type { CaptionState, TranscriptEvent, TranscriptLine, TranslationIssue } from "./types";

type Availability = "unavailable" | "downloadable" | "downloading" | "available";

interface ChromeTranslator {
  translate(text: string): Promise<string>;
  destroy(): void;
}

interface ChromeTranslatorApi {
  availability(opts: { sourceLanguage: string; targetLanguage: string }): Promise<Availability>;
  create(opts: {
    sourceLanguage: string;
    targetLanguage: string;
    monitor?: (m: EventTarget) => void;
  }): Promise<ChromeTranslator>;
}

function translatorApi(): ChromeTranslatorApi | null {
  const api = (globalThis as { Translator?: ChromeTranslatorApi }).Translator;
  return api && typeof api.create === "function" ? api : null;
}

/** Whether this browser has Chrome's built-in translator. */
export function hasTranslator(): boolean {
  return translatorApi() !== null;
}

/** Deepgram language code (`pt-BR`, `zh-TW`) → the code Chrome's translator expects (`pt`, `zh-Hant`). */
export function translatorCode(code: string): string {
  const c = code.trim().toLowerCase();
  if (c === "zh" || c.startsWith("zh-")) return /^zh-(tw|hk|mo|hant)/.test(c) ? "zh-Hant" : "zh";
  const base = c.split("-")[0] ?? c;
  return base === "iw" ? "he" : base;
}

const translators = new Map<string, Promise<ChromeTranslator>>();
const pairKey = (source: string, target: string) => `${source}>${target}`;

/** `no-api` when the browser has no built-in translator. */
export async function translatorAvailability(source: string, target: string): Promise<Availability | "no-api"> {
  const api = translatorApi();
  if (!api) return "no-api";
  try {
    // Some Chromium builds (embedded browsers) expose the API but never answer: treat that as no API.
    const timeout = new Promise<"no-api">((resolve) => setTimeout(() => resolve("no-api"), AVAILABILITY_TIMEOUT_MS));
    return await Promise.race([
      api.availability({ sourceLanguage: translatorCode(source), targetLanguage: translatorCode(target) }),
      timeout,
    ]);
  } catch {
    return "unavailable";
  }
}

const AVAILABILITY_TIMEOUT_MS = 4000;

/**
 * Start (or finish) the one-time download for a language pair. Call it straight from a click
 * or change handler: Chrome only downloads a model during a user gesture.
 * Resolves true once the pair is ready.
 */
export async function prepareTranslator(source: string, target: string, onProgress?: (fraction: number) => void): Promise<boolean> {
  const api = translatorApi();
  if (!api) return false;
  const s = translatorCode(source);
  const t = translatorCode(target);
  if (s === t) return true;
  const key = pairKey(s, t);
  const existing = translators.get(key);
  if (existing) return existing.then(() => true, () => false);
  const created = api.create({
    sourceLanguage: s,
    targetLanguage: t,
    monitor: (m) =>
      m.addEventListener("downloadprogress", (e) => onProgress?.(Number((e as Event & { loaded?: number }).loaded) || 0)),
  });
  translators.set(key, created);
  try {
    await created;
    return true;
  } catch {
    translators.delete(key);
    return false;
  }
}

/** A ready translator for the pair, or the reason there isn't one. Never downloads. */
async function readyTranslator(source: string, target: string): Promise<ChromeTranslator | TranslationIssue["kind"]> {
  const key = pairKey(source, target);
  const existing = translators.get(key);
  if (existing) return existing.catch(() => "unsupported" as const);
  const availability = await translatorAvailability(source, target);
  if (availability === "no-api") return "no-api";
  if (availability === "unavailable") return "unsupported";
  if (availability !== "available") return "download";
  const api = translatorApi()!;
  const created = api.create({ sourceLanguage: source, targetLanguage: target });
  translators.set(key, created);
  try {
    return await created;
  } catch {
    translators.delete(key);
    return "download";
  }
}

/** How long to wait before asking Chrome again about a pair that wasn't ready. */
const RECHECK_MS = 3000;

/**
 * Follows a transcript's events and emits translations of its lines and live caption.
 * The caption is translated latest-wins, so a slow translation never queues up behind
 * a speaker: while one runs, only the newest caption text waits for the next turn.
 */
export class TranslationEngine {
  private spoken = AUTO_LANGUAGE;
  private target: string | null = null;
  private generation = 0;
  private issue: TranslationIssue | null = null;
  private notReadyUntil = new Map<string, number>();
  private captionBusy = false;
  private nextCaption: CaptionState | null = null;

  constructor(private readonly emit: (event: TranscriptEvent) => void) {}

  get active(): boolean {
    return this.target !== null;
  }

  /** `spoken` is a Deepgram code or "multi"; `caption` is "" to keep the spoken language. */
  configure(spoken: string, caption: string): void {
    this.spoken = spoken || AUTO_LANGUAGE;
    const target = caption ? translatorCode(caption) : null;
    // A fixed spoken language that matches the caption language needs no translating.
    const next = target && this.spoken !== AUTO_LANGUAGE && translatorCode(this.spoken) === target ? null : target;
    if (next === this.target) return;
    this.target = next;
    this.generation += 1;
    this.issue = null;
    this.notReadyUntil.clear();
    this.emit({ type: "translation-config", target: next, issue: null });
  }

  /** Feed every transcript event here. */
  handle(event: TranscriptEvent): void {
    if (!this.target) return;
    if (event.type === "line") void this.translateLine(event.line);
    else if (event.type === "caption") this.queueCaption(event.caption);
  }

  private sourceFor(detected: string | undefined): string | null {
    const code = this.spoken === AUTO_LANGUAGE ? detected : this.spoken;
    return code ? translatorCode(code) : null;
  }

  /** The translated text, the original when it's already in the target language, or null. */
  private async translate(text: string, detected: string | undefined): Promise<string | null> {
    const target = this.target;
    const source = this.sourceFor(detected);
    if (!target || !source) return null;
    if (source === target) return text;
    const key = pairKey(source, target);
    if ((this.notReadyUntil.get(key) ?? 0) > Date.now()) return null;
    const translator = await readyTranslator(source, target);
    if (typeof translator === "string") {
      this.notReadyUntil.set(key, Date.now() + RECHECK_MS);
      this.setIssue({ source, target, kind: translator });
      return null;
    }
    try {
      const out = await translator.translate(text);
      if (this.issue) this.setIssue(null);
      return out;
    } catch {
      return null;
    }
  }

  private setIssue(issue: TranslationIssue | null) {
    const same =
      issue === this.issue ||
      (issue && this.issue && issue.kind === this.issue.kind && issue.source === this.issue.source && issue.target === this.issue.target);
    if (same) return;
    this.issue = issue;
    this.emit({ type: "translation-config", target: this.target, issue });
  }

  private async translateLine(line: TranscriptLine) {
    const generation = this.generation;
    const target = this.target;
    const text = await this.translate(line.text, line.language);
    if (text === null || !target || generation !== this.generation) return;
    this.emit({ type: "line-translated", target, id: line.id, text });
  }

  private queueCaption(caption: CaptionState) {
    this.nextCaption = caption;
    if (!this.captionBusy) void this.pumpCaptions();
  }

  private async pumpCaptions() {
    this.captionBusy = true;
    try {
      while (this.nextCaption) {
        const caption = this.nextCaption;
        this.nextCaption = null;
        const generation = this.generation;
        const target = this.target;
        if (!target) break;
        const text = caption.text ? await this.translate(caption.text, caption.language) : "";
        if (generation !== this.generation) continue;
        // Untranslatable text shows as spoken rather than leaving an older translation up.
        this.emit({ type: "caption-translated", target, text: text ?? caption.text });
      }
    } finally {
      this.captionBusy = false;
    }
  }
}

/**
 * Caption overlay, injected at runtime (chrome.scripting) into the captured tab only.
 * No `matches` → no host permissions and nothing runs on pages the user didn't choose.
 *
 * Rendered in a shadow root so the site's CSS can't touch it (and vice versa). Styles are
 * hand-written (see ./style.ts) — Tailwind v4's @property-based utilities don't apply
 * inside shadow roots.
 */
import { createRoot, type Root } from "react-dom/client";
import { createShadowRootUi } from "wxt/utils/content-script-ui/shadow-root";
import { defineContentScript } from "wxt/utils/define-content-script";
import { browser } from "wxt/browser";
import { EMPTY_CAPTION } from "@heard/shared";
import { isOverlayMessage, sendToBackground } from "@/utils/messages";
import { Overlay, createOverlayStore } from "./Overlay";
import { OVERLAY_CSS } from "./style";

const GUARD = "__heardOverlayMounted";

export default defineContentScript({
  registration: "runtime",
  async main(ctx) {
    const w = window as unknown as Record<string, unknown>;
    if (w[GUARD]) return; // already injected into this document
    w[GUARD] = true;

    const hello = await sendToBackground({ to: "background", type: "overlay-hello" }).catch(() => null);
    if (!hello?.captured) {
      w[GUARD] = false;
      return;
    }

    const store = createOverlayStore({
      status: hello.status,
      caption: hello.caption ?? EMPTY_CAPTION,
      translation: hello.captionTranslation ?? null,
      hidden: hello.hidden,
    });

    const ui = await createShadowRootUi<Root>(ctx, {
      name: "heard-captions",
      position: "inline",
      anchor: () => document.fullscreenElement ?? document.body,
      append: "last",
      css: OVERLAY_CSS,
      onMount(container) {
        const root = createRoot(container);
        root.render(
          <Overlay
            store={store}
            onDismiss={() => {
              store.set({ hidden: true });
              void sendToBackground({ to: "background", type: "overlay-dismissed" }).catch(() => undefined);
            }}
          />,
        );
        return root;
      },
      onRemove(root) {
        root?.unmount();
      },
    });
    ui.mount();

    // Fullscreen video puts one element in the top layer; anything outside it is invisible.
    const onFullscreen = () => {
      const parent = document.fullscreenElement ?? document.body;
      if (ui.shadowHost.parentElement !== parent) parent.appendChild(ui.shadowHost);
    };
    document.addEventListener("fullscreenchange", onFullscreen);

    const onMessage = (msg: unknown) => {
      if (!isOverlayMessage(msg)) return;
      const m = msg;
      switch (m.type) {
        case "event": {
          const e = m.event;
          if (e.type === "caption") store.set({ caption: e.caption });
          else if (e.type === "status") store.set({ status: e.status });
          else if (e.type === "reset") store.set({ caption: EMPTY_CAPTION, translation: null });
          else if (e.type === "caption-translated") store.set({ translation: e.text });
          else if (e.type === "translation-config" && !e.target) store.set({ translation: null });
          break;
        }
        case "show":
          store.set({ hidden: false });
          break;
        case "teardown":
          teardown();
          break;
      }
    };
    browser.runtime.onMessage.addListener(onMessage);

    function teardown() {
      browser.runtime.onMessage.removeListener(onMessage);
      document.removeEventListener("fullscreenchange", onFullscreen);
      ui.remove();
      w[GUARD] = false;
    }
    // Extension reloaded/updated: this script is orphaned.
    ctx.onInvalidated(teardown);
  },
});

/**
 * The extension's whole message protocol, in one place.
 *
 * Contexts:
 * - background (service worker): orchestrates capture, owns no transcript state.
 * - offscreen document: runs the TranscriptionSession; SOURCE OF TRUTH for session state.
 * - popup / side panel: UI; read state with `get-state`, then follow broadcasts.
 * - overlay content script: caption box inside the captured tab.
 *
 * `runtime.sendMessage` reaches every extension page at once, so every runtime message
 * carries a `to` field and each context ignores messages that aren't addressed to it.
 */
import { browser } from "wxt/browser";
import type { CaptionState, TranscriptEvent, TranscriptionStatus, TranscriptState } from "@heard/shared";

/** Everything the UI needs to render one capture session. Lives in the offscreen document. */
export interface SessionSnapshot {
  /** Tab being (or last) captured; null when nothing has been captured. */
  tabId: number | null;
  tabTitle: string | null;
  /** The user dismissed the in-page caption box for this capture. */
  overlayHidden: boolean;
  transcript: TranscriptState;
}

export type SessionMeta = Pick<SessionSnapshot, "tabId" | "tabTitle" | "overlayHidden">;

/** Generic reply for commands. `code: "needs_key"` means "the user should add their own Deepgram key". */
export type CommandResult = { ok: true } | { ok: false; error: string; code?: "needs_key" };

/**
 * How the offscreen document authenticates to Deepgram. Chosen by the background, which
 * is the only context that reads the user's key from storage. Sent only background → offscreen.
 */
export type CredentialSource = { kind: "user-key"; userKey: string } | { kind: "server"; tokenEndpoint: string };

/* ----------------------------- → background ----------------------------- */

export type BackgroundRequest =
  | { to: "background"; type: "start"; tabId: number }
  | { to: "background"; type: "stop" }
  | { to: "background"; type: "get-state" }
  /** Re-show (injecting if necessary) the caption box in the captured tab. */
  | { to: "background"; type: "show-overlay" }
  /** From the overlay: the user closed the caption box. */
  | { to: "background"; type: "overlay-dismissed" }
  /** From a freshly injected overlay: "what should I show?" (tab comes from sender). */
  | { to: "background"; type: "overlay-hello" };

export interface BackgroundResponses {
  start: CommandResult;
  stop: CommandResult;
  "get-state": SessionSnapshot;
  "show-overlay": CommandResult;
  "overlay-dismissed": CommandResult;
  "overlay-hello": OverlayHello;
}

export interface OverlayHello {
  /** False when this tab is not the captured tab: the overlay should remove itself. */
  captured: boolean;
  hidden: boolean;
  status: TranscriptionStatus;
  caption: CaptionState | null;
  /** Translation of `caption` when captions are translated. */
  captionTranslation: string | null;
}

/** Spoken language (Deepgram code or "multi") and caption language ("" = as spoken). */
export interface SessionLanguages {
  spoken: string;
  caption: string;
}

/* ----------------------------- → offscreen ----------------------------- */

export type OffscreenRequest =
  | {
      to: "offscreen";
      type: "start";
      streamId: string;
      tabId: number;
      tabTitle: string | null;
      credential: CredentialSource;
      languages: SessionLanguages;
    }
  | { to: "offscreen"; type: "set-languages"; languages: SessionLanguages }
  | { to: "offscreen"; type: "stop" }
  | { to: "offscreen"; type: "get-state" }
  | { to: "offscreen"; type: "set-overlay-hidden"; hidden: boolean };

export interface OffscreenResponses {
  start: CommandResult;
  stop: CommandResult;
  "get-state": SessionSnapshot;
  "set-overlay-hidden": CommandResult;
  "set-languages": CommandResult;
}

/* --------------------------- offscreen → everyone --------------------------- */

export type Broadcast =
  | { to: "broadcast"; type: "transcript-event"; tabId: number | null; event: TranscriptEvent }
  | { to: "broadcast"; type: "meta"; meta: SessionMeta };

/* ----------------------- background → overlay (tabs.sendMessage) ----------------------- */

export type OverlayMessage =
  | { to: "overlay"; type: "event"; event: TranscriptEvent }
  | { to: "overlay"; type: "show" }
  /** Capture ended for this tab: remove the overlay entirely. */
  | { to: "overlay"; type: "teardown" };

export type RuntimeMessage = BackgroundRequest | OffscreenRequest | Broadcast;

/* ----------------------------- typed helpers ----------------------------- */

export function sendToBackground<T extends BackgroundRequest>(msg: T): Promise<BackgroundResponses[T["type"]]> {
  return browser.runtime.sendMessage(msg);
}

export function sendToOffscreen<T extends OffscreenRequest>(msg: T): Promise<OffscreenResponses[T["type"]]> {
  return browser.runtime.sendMessage(msg);
}

/** Fire-and-forget broadcast; "no receiver" errors are expected when no UI is open. */
export function broadcast(msg: Broadcast): void {
  browser.runtime.sendMessage(msg).catch(() => undefined);
}

export function sendToOverlay(tabId: number, msg: OverlayMessage): Promise<unknown> {
  return browser.tabs.sendMessage(tabId, msg);
}

export function isRuntimeMessage(msg: unknown): msg is RuntimeMessage {
  return typeof msg === "object" && msg !== null && "to" in msg && "type" in msg;
}

export function isOverlayMessage(msg: unknown): msg is OverlayMessage {
  return typeof msg === "object" && msg !== null && (msg as { to?: unknown }).to === "overlay";
}

/** Statuses during which audio is being captured. */
export function isCapturing(status: TranscriptionStatus): boolean {
  return status === "connecting" || status === "live" || status === "paused" || status === "reconnecting";
}

/** Session errors that the user's (or the server's) Deepgram key can fix. */
export function isKeyError(message: string | null | undefined): boolean {
  return Boolean(message && /API key|Deepgram key/i.test(message));
}

export function errorMessage(err: unknown): string {
  return err instanceof Error ? err.message : String(err);
}

/**
 * Offscreen document: the only place audio is touched, and the source of truth for the
 * session (the MV3 service worker may be suspended at any time; this page is not).
 *
 * tab audio (tabCapture stream id) → getUserMedia → TranscriptionSession (@heard/shared)
 * → TranscriptEvents broadcast to the background (relays to the overlay) and to the
 * popup / side panel. Transcripts live in memory only.
 */
import { browser } from "wxt/browser";
import {
  createTokenFetcher,
  initialTranscriptState,
  reduceTranscript,
  TranscriptionSession,
  type DeepgramCredential,
} from "@heard/shared";
import {
  broadcast,
  errorMessage,
  isRuntimeMessage,
  type CommandResult,
  type OffscreenRequest,
  type OffscreenResponses,
  type SessionSnapshot,
} from "@/utils/messages";

let session: TranscriptionSession | null = null;
let transcript = initialTranscriptState();
let meta: Pick<SessionSnapshot, "tabId" | "tabTitle" | "overlayHidden"> = { tabId: null, tabTitle: null, overlayHidden: false };

function snapshot(): SessionSnapshot {
  return { ...meta, transcript };
}

function setMeta(next: Partial<typeof meta>) {
  meta = { ...meta, ...next };
  broadcast({ to: "broadcast", type: "meta", meta });
}

function userKeyCredential(key: string): () => Promise<DeepgramCredential> {
  const credential: DeepgramCredential = { type: "token", value: key };
  return async () => credential;
}

async function start(msg: Extract<OffscreenRequest, { type: "start" }>): Promise<CommandResult> {
  await stop();

  let stream: MediaStream;
  try {
    stream = await navigator.mediaDevices.getUserMedia({
      audio: { mandatory: { chromeMediaSource: "tab", chromeMediaSourceId: msg.streamId } },
      video: false,
    } as unknown as MediaStreamConstraints);
  } catch (err) {
    return { ok: false, error: `Could not capture the tab's audio: ${errorMessage(err)}` };
  }

  const tabId = msg.tabId;
  setMeta({ tabId, tabTitle: msg.tabTitle, overlayHidden: false });
  const s = new TranscriptionSession({
    // A user key is used directly (Deepgram's `token` subprotocol); no Heard server involved.
    // Otherwise each (re)connect fetches a short-lived JWT from the Heard server.
    getToken:
      msg.credential.kind === "user-key"
        ? userKeyCredential(msg.credential.userKey)
        : createTokenFetcher(msg.credential.tokenEndpoint),
    workletUrl: browser.runtime.getURL("/pcm-worklet.js"),
    // chrome.tabCapture mutes the tab for the user; route the audio back to the speakers.
    preservePlayback: true,
    onEvent: (event) => {
      transcript = reduceTranscript(transcript, event);
      broadcast({ to: "broadcast", type: "transcript-event", tabId, event });
    },
  });
  s.setLanguages(msg.languages.spoken, msg.languages.caption);
  session = s;
  // start() resolves after the first connect attempt; failures surface as status events.
  void s.start(stream);
  return { ok: true };
}

async function stop(): Promise<CommandResult> {
  const s = session;
  session = null;
  if (s) await s.stop();
  return { ok: true };
}

browser.runtime.onMessage.addListener((msg: unknown, _sender, sendResponse) => {
  if (!isRuntimeMessage(msg) || msg.to !== "offscreen") return;
  const reply = <K extends OffscreenRequest["type"]>(_type: K, value: OffscreenResponses[K] | Promise<OffscreenResponses[K]>) => {
    Promise.resolve(value).then(sendResponse, (err) => sendResponse({ ok: false, error: errorMessage(err) }));
    return true as const;
  };
  switch (msg.type) {
    case "start":
      return reply("start", start(msg));
    case "stop":
      return reply("stop", stop());
    case "get-state":
      return reply("get-state", snapshot());
    case "set-languages":
      session?.setLanguages(msg.languages.spoken, msg.languages.caption);
      return reply("set-languages", { ok: true });
    case "set-overlay-hidden":
      setMeta({ overlayHidden: msg.hidden });
      return reply("set-overlay-hidden", { ok: true });
  }
});

import { Fragment, useEffect, useLayoutEffect, useMemo, useRef, useState, type ReactNode } from "react";
import { formatTimestamp, lineTimes, type TimeBase } from "../core/format";
import type { CaptionState, TranscriptLine } from "../core/types";
import { ArrowDownIcon } from "./icons";
import { DEFAULT_TRANSCRIPT_VIEW_LABELS, type TranscriptViewLabels } from "./labels";

export interface TranscriptViewProps {
  lines: TranscriptLine[];
  /** Live caption; its text is shown as the in-progress last line. */
  caption?: CaptionState;
  live?: boolean;
  query?: string;
  timeBase?: TimeBase;
  /** When provided, timestamps become buttons that seek the media. */
  onSeek?: (seconds: number) => void;
  /** Highlight the line containing this media time (e.g. current playback position). */
  activeMediaTime?: number | null;
  emptyState?: ReactNode;
  /** Translated text by line id; translated lines show the translation with the original below. */
  translations?: Record<string, string>;
  /** Translation of the live caption, shown in place of the in-progress line. */
  captionTranslation?: string | null;
  className?: string;
  /** UI words; English by default. */
  labels?: Partial<TranscriptViewLabels>;
}

/** Live, searchable transcript with timestamps and smart auto-scroll. */
export function TranscriptView({
  lines,
  caption,
  live = false,
  query = "",
  timeBase = "stream",
  onSeek,
  activeMediaTime = null,
  emptyState,
  translations,
  captionTranslation = null,
  className = "",
  labels,
}: TranscriptViewProps) {
  const L = { ...DEFAULT_TRANSCRIPT_VIEW_LABELS, ...labels };
  const scroller = useRef<HTMLDivElement>(null);
  const [pinned, setPinned] = useState(true);
  const q = query.trim().toLowerCase();

  const visible = useMemo(
    () =>
      q
        ? lines.filter((l) => l.text.toLowerCase().includes(q) || Boolean(translations?.[l.id]?.toLowerCase().includes(q)))
        : lines,
    [lines, q, translations],
  );
  // The in-progress text is whatever the caption shows beyond the last committed line.
  const draftSource = live && !q && caption?.text && caption.text !== lines[lines.length - 1]?.text ? caption.text : "";
  const draft = draftSource && captionTranslation ? captionTranslation : draftSource;

  const activeId = useMemo(() => {
    if (activeMediaTime === null || timeBase !== "media") return null;
    let id: string | null = null;
    for (const l of lines) {
      if (l.mediaStart !== null && l.mediaStart <= activeMediaTime + 0.25) id = l.id;
    }
    return id;
  }, [lines, activeMediaTime, timeBase]);

  useLayoutEffect(() => {
    const el = scroller.current;
    if (el && pinned && !q) el.scrollTop = el.scrollHeight;
  }, [visible.length, draft, pinned, q]);

  useEffect(() => {
    const el = scroller.current;
    if (!el) return;
    const onScroll = () => setPinned(el.scrollHeight - el.scrollTop - el.clientHeight < 48);
    el.addEventListener("scroll", onScroll, { passive: true });
    return () => el.removeEventListener("scroll", onScroll);
  }, []);

  const isEmpty = visible.length === 0 && !draft;

  return (
    <div className={`relative min-h-0 flex-1 ${className}`}>
      <div
        ref={scroller}
        className="heard-scroll absolute inset-0 overflow-y-auto px-4 py-3"
        aria-live="polite"
        aria-relevant="additions"
        role="log"
        aria-label={L.region}
      >
        {isEmpty ? (
          <div className="flex h-full items-center justify-center px-6 text-center text-sm text-ink-400">
            {q ? L.noMatches(query.trim()) : emptyState ?? L.empty}
          </div>
        ) : (
          <ol className="grid grid-cols-[auto_minmax(0,1fr)] gap-x-5 gap-y-1">
            {/* One shared timestamp column, as wide as the widest timestamp, so long livestream times never touch the text. */}
            {visible.map((line) => {
              const t = lineTimes(line, timeBase);
              const seekable = Boolean(onSeek) && timeBase === "media" && line.mediaStart !== null;
              const active = line.id === activeId;
              return (
                <li
                  key={line.id}
                  className={`group col-span-2 grid grid-cols-subgrid items-baseline rounded-lg px-2 py-1.5 transition-colors ${
                    active ? "bg-ink-800" : "hover:bg-ink-850"
                  }`}
                >
                  {seekable ? (
                    <button
                      type="button"
                      onClick={() => onSeek!(t.start)}
                      className="h-fit rounded-md text-left font-mono text-xs tabular-nums text-accent hover:text-accent-strong hover:underline focus-visible:outline-2 focus-visible:outline-accent"
                      title={L.jumpTo(formatTimestamp(t.start))}
                    >
                      {formatTimestamp(t.start)}
                    </button>
                  ) : (
                    <span className="font-mono text-xs tabular-nums text-ink-500">{formatTimestamp(t.start)}</span>
                  )}
                  {translations?.[line.id] && translations[line.id] !== line.text ? (
                    <div dir="auto">
                      <p className={`text-[0.95rem] leading-relaxed ${active ? "text-ink-100" : "text-ink-200"}`}>
                        <Highlight text={translations[line.id]!} query={q} />
                      </p>
                      <p className="mt-0.5 text-[0.8rem] leading-relaxed text-ink-500" lang={line.language}>
                        <Highlight text={line.text} query={q} />
                      </p>
                    </div>
                  ) : (
                    <p dir="auto" lang={line.language} className={`text-[0.95rem] leading-relaxed ${active ? "text-ink-100" : "text-ink-200"}`}>
                      <Highlight text={line.text} query={q} />
                    </p>
                  )}
                </li>
              );
            })}
            {draft && (
              <li className="col-span-2 grid grid-cols-subgrid px-2 py-1.5">
                <span className="mt-1.5 flex items-start">
                  <span className="h-1.5 w-1.5 animate-pulse-dot rounded-full bg-live" aria-hidden="true" />
                </span>
                <p dir="auto" className="text-[0.95rem] leading-relaxed text-ink-400 italic">{draft}</p>
              </li>
            )}
          </ol>
        )}
      </div>
      {!pinned && !q && !isEmpty && (
        <button
          type="button"
          onClick={() => {
            setPinned(true);
            const el = scroller.current;
            if (el) el.scrollTo({ top: el.scrollHeight, behavior: "smooth" });
          }}
          className="absolute bottom-3 left-1/2 flex -translate-x-1/2 items-center gap-1.5 rounded-full bg-ink-700/95 px-3 py-1.5 text-xs font-medium text-ink-100 shadow-lg ring-1 ring-ink-600 backdrop-blur hover:bg-ink-600"
        >
          <ArrowDownIcon size={13} /> {live ? L.jumpToLive : L.jumpToLatest}
        </button>
      )}
    </div>
  );
}

function Highlight({ text, query }: { text: string; query: string }) {
  if (!query) return <>{text}</>;
  const parts: ReactNode[] = [];
  const lower = text.toLowerCase();
  let i = 0;
  let k = 0;
  while (i < text.length) {
    const j = lower.indexOf(query, i);
    if (j < 0) {
      parts.push(<Fragment key={k++}>{text.slice(i)}</Fragment>);
      break;
    }
    if (j > i) parts.push(<Fragment key={k++}>{text.slice(i, j)}</Fragment>);
    parts.push(
      <mark key={k++} className="heard-hit">
        {text.slice(j, j + query.length)}
      </mark>,
    );
    i = j + query.length;
  }
  return <>{parts}</>;
}

