    <div
      ref={boxRef}
      className={`box ${mode !== "idle" ? "active" : ""} ${mode === "drag" ? "dragging" : ""}`}
      style={{ left: pos.left, top: pos.top, width: pos.width }}
      onPointerDown={(e) => track(e, "drag")}
      aria-label="Heard live captions. Drag to move."
